package cn.sixnine.filmlog;

import android.app.Instrumentation;
import android.os.Bundle;
import android.content.Context;
import android.database.Cursor;
import org.json.*;
import java.io.*;
import java.util.*;

public final class PresetArtworkInstrumentation extends Instrumentation {
    private static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    private static String rows(LogStore logs,String table)throws Exception{JSONArray rows=new JSONArray();try(Cursor c=logs.getReadableDatabase().rawQuery("SELECT * FROM "+table+" ORDER BY id",null)){while(c.moveToNext()){JSONArray row=new JSONArray();for(int i=0;i<c.getColumnCount();i++)row.put(c.isNull(i)?JSONObject.NULL:c.getString(i));rows.put(row);}}return rows.toString();}
    private static CatalogStore.Batch batch(){CatalogStore.Batch b=new CatalogStore.Batch();b.id="";b.stock="Kodak Portra 800";b.format="35 mm";b.iso=800;b.capacity=36;b.quantity=3;b.threshold=1;b.location=b.temperature=b.expiry=b.purchaseDate=b.price=b.currency=b.notes="";return b;}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){waitForIdleSync();Bundle output=new Bundle();try{
        Context context=getTargetContext();check(context.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"isolation");context.deleteDatabase("film-log.db");LogStore logs=new LogStore(context);CatalogStore catalog=new CatalogStore(logs);
        String legacy=catalog.manual(UUID.randomUUID().toString(),"Historical","A handwritten stock","Camera",640,36,"35 mm","","");String shot=logs.insert(legacy,20000,-10,480,"denied","8","1/125","50mm","keep note","+1","ND3");CatalogStore.Batch b=batch();String batch=catalog.saveBatch(b,0);
        Map<String,String> original=new HashMap<>();for(String table:FilmBackup.TABLES)if(!table.equals("artwork_links")&&!table.equals("exposure_presets"))original.put(table,rows(logs,table));
        logs.getWritableDatabase().execSQL("DROP TABLE artwork_links");logs.getWritableDatabase().execSQL("DROP TABLE exposure_presets");CatalogInstrumentation.v12Catalog(logs.getWritableDatabase());logs.getWritableDatabase().setVersion(13);logs.close();logs=new LogStore(context);catalog=new CatalogStore(logs);
        check(logs.getReadableDatabase().getVersion()==24,"real v13 migration");for(String table:original.keySet())check(original.get(table).equals(rows(logs,table)),"migration preserves "+table);check(rows(logs,"artwork_links").equals("[]")&&rows(logs,"exposure_presets").equals("[]"),"no inferred historical identities");
        PresetStore presets=new PresetStore(logs);PresetStore.Item first=new PresetStore.Item();first.name="Night street";first.description="retain optional note";first.aperture="2.8";first.shutter="1/125";first.lens="35mm";presets.save(first,false);
        check(presets.list().size()==1&&presets.get(first.id).lens.equals("35mm"),"create and persistent stable ID");Bundle draft=new Bundle();draft.putString("memo","keep #Portrait");draft.putString("filters","ND3");draft.putString("offset","-10");draft.putString("ev","+1");presets.get(first.id).preset().apply(draft);check(draft.getString("lens").equals("35mm")&&draft.getString("ev").isEmpty()&&draft.getString("memo").equals("keep #Portrait")&&draft.getString("offset").equals("-10"),"custom apply preserves capture and memo, clears EV");
        PresetStore.Item edit=presets.get(first.id);edit.name="Edited";edit.description=edit.aperture=edit.shutter=edit.lens="";presets.save(edit,true);check(presets.get(first.id).aperture.equals("2.8")&&presets.get(first.id).lens.equals("35mm")&&presets.get(first.id).description.equals("retain optional note"),"original empty optional edit retains values");
        PresetStore.Item duplicate=new PresetStore.Item();duplicate.name=" edited ";try{presets.save(duplicate,false);throw new AssertionError("duplicate name accepted");}catch(IllegalArgumentException expected){}
        String validPresets=rows(logs,"exposure_presets");edit.name="  ";try{presets.save(edit,true);throw new AssertionError("blank name saved");}catch(IllegalArgumentException expected){}check(rows(logs,"exposure_presets").equals(validPresets),"invalid edit atomic");
        for(String icon:PresetStore.ICONS){PresetStore.Item item=new PresetStore.Item();item.name=icon;item.icon=icon;presets.save(item,false);check(PresetStore.iconCode(icon)>0&&PresetStore.iconColor(icon)!=0,"original icon/color");presets.delete(item.id);}check(presets.list().size()==1,"delete only specified custom item");for(String table:original.keySet())check(original.get(table).equals(rows(logs,table)),"preset CRUD never edits "+table);
        ArtworkLinks.set(context,logs,"roll",legacy,"original:kodak_portra_800");ArtworkLinks.set(context,logs,"batch",batch,"original:kodak_portra_800");for(String table:original.keySet())check(original.get(table).equals(rows(logs,table)),"explicit link preserves snapshot "+table);
        String links=rows(logs,"artwork_links");ArtworkLinks.set(context,logs,"roll",legacy,"original:kodak_portra_800");check(links.equals(rows(logs,"artwork_links")),"repeated association preserves link ID");try{ArtworkLinks.set(context,logs,"roll",legacy,"original:not_real");throw new AssertionError("unknown original linked");}catch(IllegalArgumentException expected){}check(links.equals(rows(logs,"artwork_links")),"invalid association keeps prior link");
        String loaded=catalog.load(batch,UUID.randomUUID().toString(),"Linked load","","");check(ArtworkLinks.get(logs,"roll",loaded).equals("original:kodak_portra_800")&&catalog.batch(batch).quantity==2,"load copies exact stock ID and consumes once");ArtworkLinks.set(context,logs,"batch",batch,"original:kodak_ultramax_400");check(ArtworkLinks.get(logs,"roll",loaded).equals("original:kodak_portra_800"),"batch relink never rewrites loaded history");
        CatalogStore.Batch selected=batch();selected.stockId="original:kodak_portra_800";String selectedBatch=catalog.saveBatch(selected,0);check(ArtworkLinks.get(logs,"batch",selectedBatch).equals(selected.stockId),"new selected stock ID retained");selected.stock="User changed identity";catalog.saveBatch(selected,3);check(ArtworkLinks.get(logs,"batch",selectedBatch).isEmpty(),"edited identity cannot keep a stale selected ID");
        String manual=catalog.manual(UUID.randomUUID().toString(),"Direct","Kodak Portra 800","Camera",800,36,"35 mm","","","original:kodak_portra_800");check(ArtworkLinks.get(logs,"roll",manual).equals("original:kodak_portra_800"),"manual load exact selection ID");check(ArtworkLinks.selected(context,"original:kodak_portra_800","Kodak Portra 800",800,"110").isEmpty(),"format mismatch never links");
        ByteArrayOutputStream archive=new ByteArrayOutputStream();FilmBackup.write(context,logs,archive);int before=logs.rolls().size();String exposureBefore=rows(logs,"shots");
        try(FilmBackup.Prepared prepared=FilmBackup.inspect(context,new ByteArrayInputStream(archive.toByteArray()))){check(prepared.manifest.getInt("schema")==25&&prepared.count("exposure_presets")==1&&prepared.count("artwork_links")==4,"extras included in backup");FilmBackup.restore(context,logs,prepared);check(logs.rolls().size()==before*2&&presets.list().size()==2,"append restore with fresh IDs");Set<String> oldOwners=new HashSet<>(Arrays.asList(legacy,loaded,manual,batch));int restored=0;try(Cursor c=logs.getReadableDatabase().rawQuery("SELECT owner_kind,owner_id,stock_id FROM artwork_links",null)){while(c.moveToNext()){String kind=c.getString(0),owner=c.getString(1);if(!oldOwners.contains(owner)){restored++;if(kind.equals("roll"))logs.roll(owner);else catalog.batch(owner);}ArtworkLinks.original(context,c.getString(2));}}check(restored==4,"all restored owner IDs remapped, original stock IDs retained");
            JSONObject bad=prepared.manifest.getJSONArray("artwork_links").getJSONObject(0);String goodOwner=bad.getString("owner_id");bad.put("owner_id","missing");int count=logs.rolls().size();String unchanged=rows(logs,"artwork_links");try{FilmBackup.restore(context,logs,prepared);throw new AssertionError("bad FK accepted");}catch(IOException expected){}check(logs.rolls().size()==count&&rows(logs,"artwork_links").equals(unchanged),"bad owner restore atomic");bad.put("owner_id",goodOwner);
            prepared.manifest.put("schema",13);prepared.manifest.remove("artwork_links");prepared.manifest.remove("exposure_presets");FilmBackup.normalizeCatalog(prepared.manifest);check(prepared.count("artwork_links")==0&&prepared.count("exposure_presets")==0,"legacy backup does not fabricate association");FilmBackup.restore(context,logs,prepared);check(rows(logs,"artwork_links").equals(unchanged),"old restore leaves existing associations untouched");
        }
        ArtworkLinks.set(context,logs,"roll",legacy,"");check(ArtworkLinks.get(logs,"roll",legacy).isEmpty()&&logs.shot(shot).captured==10000&&logs.shot(shot).memo.equals("keep note")&&logs.roll(legacy).iso==640,"unlink preserves historical parameters/time");presets.delete(first.id);check(logs.shot(shot).aperture.equals("8")&&presets.list().size()==1,"deleting source preset never edits records or imported copy");logs.close();output.putString("stream","PASS: v13 migration preserves nine tables; preset create/edit/null-retain/delete; 10 icons; stable artwork identity/new-load/manual-link/non-cascade; schema14 append/remap/invalid rollback/schema13 compatibility\n");finish(-1,output);
    }catch(Throwable error){output.putString("stream",android.util.Log.getStackTraceString(error));finish(0,output);}}
}
